import uuid
from datetime import datetime

from sqlalchemy import DateTime, MetaData, Uuid, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# Naming convention keeps autogenerated Alembic migrations deterministic and
# keeps constraint names readable in psql / error messages.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class TenantScopedMixin:
    """Mixin for every table that participates in row-level security.

    tenant_id is indexed (not unique) — RLS policies filter on it on every
    query, so it needs to be cheap to look up. The column is NOT a foreign key
    to a `tenants` table on purpose: there is no tenants table in this database
    at all, because each database only ever serves the one tenant whose
    deployment is talking to it. The column exists purely so RLS has something
    to compare against `current_setting('app.tenant_id')`.
    """

    id: Mapped[uuid.UUID] = mapped_column(
        Uuid(as_uuid=True), primary_key=True, server_default=func.gen_random_uuid()
    )
    tenant_id: Mapped[uuid.UUID] = mapped_column(Uuid(as_uuid=True), nullable=False, index=True)


class TimestampMixin:
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )


class UpdatedAtMixin:
    # Deliberately no `onupdate=func.now()`: that would make Postgres compute
    # the new value on UPDATE, which then requires an async post-UPDATE
    # SELECT to read it back before the ORM object can be serialized into a
    # response — triggering a MissingGreenlet error under AsyncSession
    # outside of extra `session.refresh()` plumbing. Simpler to just have
    # whichever code path mutates the row set this explicitly in Python.
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )
